import Link from 'next/link';

export const ServiceCard = ({ title, description, link, image, attribution }) => (
	<div className='card-service bg-white flex flex-col h-full shadow-lg group'>
		<div className='relative w-full aspect-video overflow-hidden bg-[#2c3e50]/5 shrink-0'>
			<img src={image} alt={title} className='w-full h-full object-cover group-hover:scale-105 transition-transform duration-700' />
			{attribution && (
				<span className='absolute bottom-1 right-2 text-[7px] text-white/50 uppercase tracking-tighter pointer-events-none group-hover:text-white/80 transition-opacity italic z-10'>
					{attribution}
				</span>
			)}
		</div>

		<div className='p-6 flex flex-col flex-grow justify-between'>
			<div className='space-y-3'>
				<h3 className='text-xl font-bold text-[#2c3e50] group-hover:text-[#e67e22] transition-colors leading-snug uppercase'>{title}</h3>
				<p className='text-sm text-[#778696] font-light leading-relaxed line-clamp-3'>{description}</p>
			</div>

			<div className='mt-6 pt-4 border-t border-gray-100'>
				<Link href={link} className='inline-flex items-center gap-2 text-xs font-bold uppercase tracking-wider text-[#e67e22] hover:text-[#2c3e50] transition-colors'>
					Ver detalles <span className='transition-transform group-hover:translate-x-1'>&rarr;</span>
				</Link>
			</div>
		</div>
	</div>
);
